class Solution {
  public long maxTotal(int[] value, int[] limit) {
    int n = value.length;
    java.util.PriorityQueue<Integer>[] heaps = new java.util.PriorityQueue[n + 1];
    long total = 0;
    for (int i = 0; i < n; i++) {
      int l = limit[i];
      if (heaps[l] == null) heaps[l] = new java.util.PriorityQueue<>();
      heaps[l].add(value[i]);
      total += value[i];
      if (heaps[l].size() > l) total -= heaps[l].poll();
    }
    return total;
  }
}
